function EVALUATE-REPRESENTATION(char_table, n, a):
    a <- a mod n
    if a in char_table: return char_table[a]   # D(a)
    else: return 0                              # non-unit residue

function COUNT-REPRESENTATIONS(n):
    count <- 0
    for a in 1..n:
        if gcd(a, n) = 1: count <- count + 1
    return count        # = phi(n)

